Pattern.Snippet:
```kotlin
/**
 * @purpose Stateless counter display + increment. Callers own the count state.
 * @param count Current count value.
 * @param onIncrement Fires when the user presses the increment button.
 * @param modifier External placement.
 */
@Composable
fun Counter(
    count: Int,
    onIncrement: () -> Unit,
    modifier: Modifier = Modifier,
) {
    Row(modifier) {
        Text(text = count.toString())
        Button(onClick = onIncrement) { Text("+") }
    }
}

/**
 * @purpose Convenience wrapper. Owns state; rarely the right export.
 * @invariant State survives config change via rememberSaveable.
 */
@Composable
fun CounterStateful(modifier: Modifier = Modifier) {
    var count by rememberSaveable { mutableStateOf(0) }
    Counter(count = count, onIncrement = { count++ }, modifier = modifier)
}
```

```kotlin
@Composable
fun OrderDetail(orderId: OrderId, viewModel: OrderViewModel) {
    LaunchedEffect(orderId) {
        viewModel.loadOrder(orderId)
    }
    val state by viewModel.state.collectAsStateWithLifecycle()
    OrderContent(state)
}
```

```kotlin
@Composable
fun TrackScreen(screenName: String, analytics: Analytics) {
    DisposableEffect(screenName) {
        analytics.startScreenView(screenName)
        onDispose { analytics.endScreenView(screenName) }
    }
}
```

```kotlin
@Composable
fun SaveButton(onSave: suspend () -> Unit) {
    val scope = rememberCoroutineScope()
    Button(onClick = {
        scope.launch { onSave() }
    }) { Text("Save") }
}
```

```kotlin
import kotlinx.collections.immutable.ImmutableList
import kotlinx.collections.immutable.persistentListOf

/**
 * @purpose Render an ordered list. Skippable when `items` reference is unchanged.
 * @param items Immutable list of orders. Structural equality drives skipping per AX_STABILITY_AND_SKIPPING.
 */
@Composable
fun OrderList(items: ImmutableList, modifier: Modifier = Modifier) {
    LazyColumn(modifier) {
        items(items, key = { it.id.value }) { order ->
            OrderRow(order)
        }
    }
}
```

