```kotlin
// ViewModel per kotlin-coroutines PT_FLOW_STATE_IN_UI:
// val orders: StateFlow = ... .stateIn(viewModelScope, WhileSubscribed(5_000), Loading)

@Composable
fun OrdersScreen(viewModel: OrdersViewModel) {
    val state by viewModel.orders.collectAsStateWithLifecycle()
    when (val s = state) {
        is Loading -> LoadingIndicator()
        is Loaded  -> OrderList(s.items)
        is Failed  -> ErrorPanel(s.cause)
    }
}
```

AntiPattern.Good:
```kotlin
@Composable
fun Good(onTick: () -> Unit) {
    var x by remember { mutableStateOf(0) }
    LaunchedEffect(Unit) {
        while (true) { delay(1.seconds); x++ } // writes from a side-effect scope
    }
    Text("$x")
}
```

